package dk.jamesbabz.madkursus.tools.recipetemplate;
import java.nio.file.*;import java.util.*;
public final class RecipeTemplateDraftCli {
 public static void main(String[] args)throws Exception{List<String>a=new ArrayList<>(List.of(args));String mode=System.getProperty("recipeTemplateDraft.mode","");boolean process="process".equals(mode),write="import".equals(mode)||a.remove("--import"),update=a.remove("--update"),dryRun=a.remove("--dry-run"),regenerateAdd=a.remove("--regenerate-add");if(a.size()!=1||regenerateAdd&&!process||regenerateAdd&&dryRun)throw new IllegalArgumentException("Usage: <draft.json> [--dry-run|--regenerate-add|--update]");var tool=new RecipeTemplateDraftTool(Path.of("."));if(process){var processed=regenerateAdd?tool.regenerateAddMigration(Path.of(a.getFirst()),null):tool.processDraft(Path.of(a.getFirst()),dryRun,null);var result=processed.validation();System.out.println("RecipeTemplate: "+result.key());System.out.println("Status: valid");System.out.println("Action: "+processed.action()+(regenerateAdd?" (recovery regeneration)":""));if(processed.existingName()!=null)System.out.println("Existing template: "+result.key()+" - "+processed.existingName());processed.warnings().forEach(v->System.out.println("Warning:\n"+v));System.out.println("Canonical source updated: "+(dryRun?"no (dry run)":regenerateAdd?"no (recovery mode)":"yes"));System.out.println("Migration candidate:\n"+processed.migration());System.out.println("Summary: "+result.ingredients()+" ingredients, "+result.components()+" components, "+result.preparation()+" preparation steps, "+result.processes().size()+" cooking processes");if(processed.action()==RecipeTemplateDraftTool.Action.UPDATE)System.out.println("Stable RecipeTemplate ID preserved: yes");return;}var result=write?tool.importDraft(Path.of(a.getFirst()),update,null):tool.validate(Path.of(a.getFirst()));System.out.println("RecipeTemplate: "+result.key()+" - "+result.name());System.out.println("Status: valid");System.out.println("Ingredients: "+result.ingredients());System.out.println("Prepared components: "+result.components());System.out.println("Preparation steps: "+result.preparation());System.out.println("Cooking processes:");result.processes().forEach(v->System.out.println("- "+v));System.out.println("Warnings: "+(result.warnings().isEmpty()?"none":String.join("; ",result.warnings())));if(write){System.out.println("Mode: "+(result.update()?"update":"new"));System.out.println("Files changed:\n- "+result.canonical()+"\n- "+result.migration());System.out.println("Review git diff, rename V_NEXT deliberately, then run: gradlew cleanTest test");}else System.out.println("No files changed.");}
}
